import React, { useState } from 'react';
// CSS 파일은 AdminPage.css를 사용한다고 했으니 별도의 import는 필요 없어!
// 하지만 만약 AccountInfoTab만을 위한 CSS 파일이 있다면 import 해주면 돼.
// import './AccountInfoTab.css'; 

const AccountInfoTab = ({ adminInfo }) => {
  const [isEditing, setIsEditing] = useState(false);
  const [formData, setFormData] = useState(adminInfo);

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    // 실제 백엔드 관리자 계정 정보 수정 API 호출 로직
    alert('관리자 계정 정보가 성공적으로 수정되었습니다! 🥳 (API 연동 필요)');
    console.log('수정된 관리자 정보:', formData);
    setIsEditing(false);
  };

  return (
    <div className="tab-content-section account-info-tab"> {/* AdminPage.css의 .tab-content-section 사용 */}
      <h3 className="tab-content-title">계정 정보 {!isEditing ? '보기' : '수정'}</h3> {/* AdminPage.css의 .tab-content-title 사용 */}

      {!isEditing ? (
        <>
          <div className="info-item">
            <span className="info-label">이름</span>
            <span className="info-value">{adminInfo.name}</span>
          </div>
          <div className="info-item">
            <span className="info-label">이메일</span>
            <span className="info-value">{adminInfo.email}</span>
          </div>
          <div className="info-item">
            <span className="info-label">역할</span>
            <span className="info-value">{adminInfo.role}</span>
          </div>
          <div className="info-item">
            <span className="info-label">마지막 로그인</span>
            <span className="info-value">{adminInfo.lastLogin}</span>
          </div>
          <div className="button-group" style={{ display: 'flex', justifyContent: 'center', gap: '15px', marginTop: '40px' }}> {/* 인라인 스타일 유지 또는 AdminPage.css에 추가 가능 */}
            <button className="action-button" onClick={() => setIsEditing(true)}>정보 수정 ✏️</button> {/* AdminPage.css의 .action-button 사용 */}
          </div>
        </>
      ) : (
        <form onSubmit={handleSubmit}>
          <div className="info-item">
            <label className="info-label" htmlFor="adminName">이름</label>
            <input
              type="text"
              id="adminName"
              name="name"
              value={formData.name}
              onChange={handleChange}
              className="info-value-input" // 이 클래스는 AdminPage.css에 없으므로, 필요하다면 추가해줘!
              required
            />
          </div>
          <div className="info-item">
            <label className="info-label" htmlFor="adminEmail">이메일</label>
            <input
              type="email"
              id="adminEmail"
              name="email"
              value={formData.email}
              onChange={handleChange}
              className="info-value-input" // 이 클래스는 AdminPage.css에 없으므로, 필요하다면 추가해줘!
              required
            />
          </div>
          {/* 비밀번호 변경 등 추가 필드는 필요하면 이 곳에 넣어줘! */}
          <div className="button-group" style={{ display: 'flex', justifyContent: 'center', gap: '15px', marginTop: '40px' }}> {/* 인라인 스타일 유지 */}
            <button type="submit" className="action-button">저장 ✅</button>
            <button type="button" className="action-button secondary" onClick={() => setIsEditing(false)}>취소 ↩️</button> {/* secondary 클래스는 AdminPage.css에 없으므로, 필요하다면 추가해줘! */}
          </div>
        </form>
      )}
    </div>
  );
};

export default AccountInfoTab;
